      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f para determinar se as atividades alteradas afetam o término e em que magnitude."
    ],
    "motivo": "As durações aumentam, mas não há suporte para concluir se isso altera o término final ou quantos dias acrescenta.",
    "unidade": "dia_corrido"
  },
