    "estado": "exato",
    "valor": 165000,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      }
    ],
    "lacunas": [],
    "motivo": "O custo da linha base é R$ 1.650,00, consistente com as obrigações fixas e o apoio exclusivo.",
    "unidade": "BRL_centavo"
  },
  "custo_novo": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Faltam as precedências da ficha d_a70f e, portanto, o novo término necessário para calcular eventual custo adicional de apoio."
    ],
    "motivo": "As obrigações fixas não variam, mas o custo do apoio depende da duração; não é possível determinar se haverá dias extras além dos já previstos na base.",
    "unidade": "BRL_centavo"
  },
  "delta_centavos": {
    "estado": "indeterminado",
    "valor": null,
    "direcao": "desconhecida",
    "evidencias": [
      {
        "fonte_id": "f_113c08",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_493d",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_b915",
        "localizador": "L01"
      },
      {
        "fonte_id": "f_36c2",
        "localizador": "L02"
      }
    ],
    "lacunas": [
      "Sem as precedências e o novo término, não se determina se há extensão adicional do apoio nem seu valor."
    ],
    "motivo": "O aviso não tem cobrança direta e os custos fixos permanecem, mas eventual variação do apoio depende do término final.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "A linha base informa D12 e R$ 1.650,00. O aviso altera as durações de duas atividades sem cobrança direta. Como a ficha de precedências referida na fonte f_36c2 não foi fornecida, não se pode calcular o efeito sobre o término final nem sobre o custo variável do apoio."
}

